-- Generated by npm run db:build. Add per-language footer links without changing existing contact or mail settings.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE site_settings SET configuration = JSON_SET(configuration, '$.contact.socialLinks', CAST(CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON))
WHERE id='contact' AND JSON_VALID(configuration) AND NOT JSON_CONTAINS_PATH(configuration, 'one', '$.contact.socialLinks');
INSERT INTO app_migrations (id) SELECT '2026-10-social-links-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-social-links-v1');
COMMIT;
